#!/usr/bin/env bash
# Week-1 real implementation installer. Run from the TokenGuard repo root.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Week-1 real files..."
decode "src/tokenguard/llm/generate.py" << 'B64EOF'

B64EOF
decode "src/tokenguard/reasoning/datasets.py" << 'B64EOF'

B64EOF
decode "src/tokenguard/baselines/halting.py" << 'B64EOF'

B64EOF
decode "src/tokenguard/baselines/prompts.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_week1_harness.py" << 'B64EOF'

B64EOF
decode "tests/test_reasoning.py" << 'B64EOF'

B64EOF
decode "tests/test_baselines.py" << 'B64EOF'

B64EOF
echo ""; echo "Week-1 files installed. Run: python -m pytest tests/test_reasoning.py tests/test_baselines.py -q"